import {describe, it, expect, afterEach} from 'vitest';
import {mkdtempSync, readFileSync, rmSync, writeFileSync} from 'fs';
import {tmpdir} from 'os';
import {join} from 'path';
import {applyGameSoundOutput, soundMapTags, speakerTagsFromListXml, withSoundOutput} from '@/class/MameSoundMap';

const HDMI = 'vc4-hdmi-0, MAI PCM i2s-hifi-0';

// R-Type II's cfg file as MAME 0.289 wrote it on a Raspberry Pi 4, its sound on the jack.
const RTYPE2_CFG = `<?xml version="1.0"?>
<!-- This file is autogenerated; comments and unknown tags will be stripped -->
<mameconfig version="10">
    <system name="rtype2">
        <counters>
            <coins index="0" number="56" />
        </counters>
        <mixer>
            <audio_effects tag=":speaker">
                <effect step="1" type="Filters" />
            </audio_effects>
            <sound_map tag=":speaker">
                <node_mapping node="o:bcm2835 Headphones, bcm2835 Headphones" db="0.000000" />
            </sound_map>
        </mixer>
    </system>
</mameconfig>
`;

describe('speakers of a game', () => {
    it('reads them from -listxml', () => {
        const xml = '<machine name="rtype2"><device_ref tag=":speaker" name="speaker"/><device_ref tag=":m72" name="m72_audio"/>'
            + '<chip type="audio" tag="speaker" name="Speaker"/></machine>';
        expect(speakerTagsFromListXml(xml)).toEqual([':speaker']);
        expect(speakerTagsFromListXml('<device_ref tag=":lspeaker" name="speaker"/><device_ref tag=":rspeaker" name="speaker"/>'))
            .toEqual([':lspeaker', ':rspeaker']);
    });

    it('reads them from a cfg file, an empty <sound_map/> included', () => {
        expect(soundMapTags(RTYPE2_CFG)).toEqual([':speaker']);
        expect(soundMapTags('<mixer><sound_map tag=":mono" /></mixer>')).toEqual([':mono']);
    });
});

describe('withSoundOutput', () => {
    it('replaces the output a speaker had, and keeps the rest of the file', () => {
        const next = withSoundOutput(RTYPE2_CFG, 'rtype2', [':speaker'], HDMI);
        expect(next).toContain(`<node_mapping node="o:${HDMI}" db="0.000000" />`);
        expect(next).not.toContain('Headphones');
        expect(next).toContain('<coins index="0" number="56" />');
        expect(next).toContain('<effect step="1" type="Filters" />');
    });

    it('fills an empty <sound_map/> in', () => {
        const next = withSoundOutput('<mixer>\n            <sound_map tag=":speaker" />\n        </mixer>', 'rtype2', [':speaker'], HDMI);
        expect(soundMapTags(next)).toEqual([':speaker']);
        expect(next).toContain(`node="o:${HDMI}"`);
    });

    it('adds the speakers a file does not map yet', () => {
        const next = withSoundOutput('<mameconfig version="10">\n    <system name="dkong">\n    </system>\n</mameconfig>\n', 'dkong', [':mono'], HDMI);
        expect(next).toContain('<mixer>');
        expect(soundMapTags(next)).toEqual([':mono']);
    });

    it('writes a whole file for a game played for the first time', () => {
        const next = withSoundOutput(null, 'dkong', [':mono'], HDMI);
        expect(next).toContain('<system name="dkong">');
        expect(soundMapTags(next)).toEqual([':mono']);
        expect(next).toContain(`node="o:${HDMI}"`);
    });
});

describe('applyGameSoundOutput', () => {
    let dir: string;
    afterEach(() => rmSync(dir, {recursive: true, force: true}));

    it('maps the speakers the cfg file has, without asking MAME', () => {
        dir = mkdtempSync(join(tmpdir(), 'maui-cfg-'));
        writeFileSync(join(dir, 'rtype2.cfg'), RTYPE2_CFG);
        let asked = false;
        applyGameSoundOutput(dir, 'rtype2', HDMI, () => {
            asked = true;
            return [];
        });
        expect(asked).toBe(false);
        expect(readFileSync(join(dir, 'rtype2.cfg'), 'utf8')).toContain(`node="o:${HDMI}"`);
    });

    it('asks MAME for the speakers of a game without a cfg file', () => {
        dir = mkdtempSync(join(tmpdir(), 'maui-cfg-'));
        const cfgDir = join(dir, 'cfg');
        applyGameSoundOutput(cfgDir, 'dkong', HDMI, () => [':mono']);
        expect(soundMapTags(readFileSync(join(cfgDir, 'dkong.cfg'), 'utf8'))).toEqual([':mono']);
    });
});
